SELECT /*+ INDEX(o IX_ORD_CUST) */ , c.CUST_NAME
  FROM ORDERS o, CUSTOMER c

  o.CUST_ID = c.CUST_ID(+)
  AND o.CUST_ID = #{custId}
  AND o.STATUS = #{status}

    AND o.ORDER_ID IN
    #{oid}



  ORDER BY ${sortColumn}
  ORDER BY o.ORDER_ID

SELECT LEVEL, CAT_ID, PARENT_ID FROM CATEGORY
 START WITH CAT_ID = #{root}
CONNECT BY PRIOR CAT_ID = PARENT_ID

SELECT ORDER_ID FROM ORDERS

  AND COL_A = #{a}
  AND COL_B = #{b}
  AND COL_C = #{c}
  AND COL_D = #{d}
  AND COL_E = #{e}
  AND COL_F = #{f}
  AND COL_G = #{g}
